// -----------------------------------------------------------------------------
// Author: Simone Machetti
//
// Description:
//   Self-checking testbench for the full BFP PE datapath, with the integer
//   datapath alongside as reference: the mantissa dispatchers feed both
//   pe_array -> acc_array (baseline) and pe_array_bfp -> acc_array_bfp (BFP),
//   while the exponent dispatchers feed the BFP tree and accumulator. Every
//   mode runs twice per vector:
//
//   Pass A (equal exponents): every BFP aligner is bit-transparent, so the BFP
//   output must be bit-identical to the baseline at pe_out - single-shot and
//   through the seed + NUM_ACC-1 feedback accumulation - while the baseline
//   itself matches the matmul golden (seed + NUM_ACC * result), and every
//   accumulator exponent equals the common scale.
//
//   Pass B (per-mode BFP exponents, seed at the minimum scale 0): the running
//   accumulator scale must equal the tap scale, and because a min-scale seed
//   floors once on the first alignment and every later feedback add sits at the
//   stable tap scale, the accumulator value is exactly
//   (seed >>> tap_exp) + NUM_ACC * tap, read directly from the BFP tap - a
//   bit-exact check of the in-loop alignment and the running-max exponent.
//
// Parameters:
//   NUM_RAND - number of random A,B matrix pairs per mode
//   NUM_ACC  - iterations in the accumulation pass
// -----------------------------------------------------------------------------

`timescale 1 ns/1 ps

`ifndef CLK_PERIOD_NS
`define CLK_PERIOD_NS 10
`endif

