    logic [   SEL_WIDTH-1:0] sel_b       [0:NUM_PAIR-1];
    logic [    OP_WIDTH-1:0] ctr_l       [0:NUM_PAIR-1];
    logic [    OP_WIDTH-1:0] ctr_h       [0:NUM_PAIR-1];
    logic [ A_DP8_WIDTH-1:0] a_dp8       [ 0:NUM_DP8-1];
    logic [ B_DP8_WIDTH-1:0] b_dp8       [ 0:NUM_DP8-1];
    logic                    is_signed_a [ 0:NUM_DP8-1];
    logic                    is_signed_b [ 0:NUM_DP8-1];
    logic [   NUM_SHIFT-1:0] sel_shift;
    logic [             2:0] en_level;
    logic [L0_TAP_WIDTH-1:0] l0_sum      [  0:NUM_L0-1];
    logic [L0_TAP_WIDTH-1:0] l0_carry    [  0:NUM_L0-1];
    logic [L1_TAP_WIDTH-1:0] l1_sum      [  0:NUM_L1-1];
    logic [L1_TAP_WIDTH-1:0] l1_carry    [  0:NUM_L1-1];
    logic [L2_TAP_WIDTH-1:0] l2_sum      [  0:NUM_L2-1];
    logic [L2_TAP_WIDTH-1:0] l2_carry    [  0:NUM_L2-1];
    logic [L3_TAP_WIDTH-1:0] l3_sum;
    logic [L3_TAP_WIDTH-1:0] l3_carry;

    localparam int NUM_LANE = 8;
    localparam int ACC_W    = 20;

    logic [ACC_W-1:0] acc_word   [0:NUM_LANE-1];
    logic [      1:0] sel_out;
    logic             sel_acc;
    logic             prop_carry;
    logic [ACC_W-1:0] pe_out     [0:NUM_LANE-1];

    // BFP exponent sideband + BFP datapath signals.
    logic [ EXP_A_WIDTH-1:0] pe_exp_a;
    logic [ EXP_B_WIDTH-1:0] pe_exp_b;
    logic [EXP_IN_WIDTH-1:0] exp_a_dp8  [0:NUM_DP8-1];
    logic [EXP_IN_WIDTH-1:0] exp_b_dp8  [0:NUM_DP8-1];
    logic [EXP_IN_WIDTH-1:0] gold_exp_a [0:NUM_DP8-1];
    logic [EXP_IN_WIDTH-1:0] gold_exp_b [0:NUM_DP8-1];
    logic [   EXP_WIDTH-1:0] exp_dp8    [0:NUM_DP8-1];

    logic [L0_TAP_WIDTH-1:0] b_l0_sum   [0:NUM_L0-1];
    logic [L0_TAP_WIDTH-1:0] b_l0_carry [0:NUM_L0-1];
    logic [   EXP_WIDTH-1:0] b_l0_exp   [0:NUM_L0-1];
    logic [L1_TAP_WIDTH-1:0] b_l1_sum   [0:NUM_L1-1];
    logic [L1_TAP_WIDTH-1:0] b_l1_carry [0:NUM_L1-1];
    logic [   EXP_WIDTH-1:0] b_l1_exp   [0:NUM_L1-1];
    logic [L2_TAP_WIDTH-1:0] b_l2_sum   [0:NUM_L2-1];
    logic [L2_TAP_WIDTH-1:0] b_l2_carry [0:NUM_L2-1];
    logic [   EXP_WIDTH-1:0] b_l2_exp   [0:NUM_L2-1];
    logic [L3_TAP_WIDTH-1:0] b_l3_sum;
    logic [L3_TAP_WIDTH-1:0] b_l3_carry;
    logic [   EXP_WIDTH-1:0] b_l3_exp;

    logic [   EXP_WIDTH-1:0] acc_exp_word [0:NUM_LANE-1];
    logic [       ACC_W-1:0] b_pe_out     [0:NUM_LANE-1];
    logic [   EXP_WIDTH-1:0] b_pe_exp     [0:NUM_LANE-1];

    logic signed [15:0] A_re [0:MAXM-1][0:MAXK-1];
    logic signed [15:0] A_im [0:MAXM-1][0:MAXK-1];
    logic signed [15:0] B_re [0:MAXK-1][0:MAXN-1];
    logic signed [15:0] B_im [0:MAXK-1][0:MAXN-1];
    longint             X_re [0:MAXO-1];
    longint             X_im [0:MAXO-1];

    int err;
    int npass;

    disp_array_a disp_array_a_i (
        .clk_i    (clk_i),
        .rst_ni   (rst_ni),
        .pe_in_a_i(pe_in_a),
        .sel_a_i  (sel_a),
        .a_dp8_o  (a_dp8)
    );

    disp_array_b disp_array_b_i (
        .clk_i    (clk_i),
        .rst_ni   (rst_ni),
        .pe_in_b_i(pe_in_b),
        .sel_b_i  (sel_b),
        .ctr_l_i  (ctr_l),
        .ctr_h_i  (ctr_h),
        .b_dp8_o  (b_dp8)
    );

    pe_array pe_array_i (
        .clk_i        (clk_i),
        .rst_ni       (rst_ni),
        .a_dp8_i      (a_dp8),
        .b_dp8_i      (b_dp8),
        .is_signed_a_i(is_signed_a),
        .is_signed_b_i(is_signed_b),
        .sel_shift_i  (sel_shift),
        .en_level_i   (en_level),
        .l0_sum_o     (l0_sum),
        .l0_carry_o   (l0_carry),
        .l1_sum_o     (l1_sum),
        .l1_carry_o   (l1_carry),
        .l2_sum_o     (l2_sum),
        .l2_carry_o   (l2_carry),
        .l3_sum_o     (l3_sum),
        .l3_carry_o   (l3_carry)
    );

    acc_array acc_array_i (
        .clk_i       (clk_i),
        .rst_ni      (rst_ni),
        .l0_sum_i    (l0_sum),
        .l0_carry_i  (l0_carry),
        .l1_sum_i    (l1_sum),
        .l1_carry_i  (l1_carry),
        .l2_sum_i    (l2_sum),
        .l2_carry_i  (l2_carry),
        .l3_sum_i    (l3_sum),
        .l3_carry_i  (l3_carry),
        .acc_i       (acc_word),
        .sel_out_i   (sel_out),
        .sel_acc_i   (sel_acc),
        .prop_carry_i(prop_carry),
        .pe_out_o    (pe_out)
    );

    disp_array_exp_a_bfp disp_array_exp_a_bfp_i (
        .clk_i      (clk_i),
        .rst_ni     (rst_ni),
        .pe_exp_a_i (pe_exp_a),
        .sel_a_i    (sel_a),
        .ctr_l_i    (ctr_l),
        .ctr_h_i    (ctr_h),
        .exp_a_dp8_o(exp_a_dp8)
    );

    disp_array_exp_b_bfp disp_array_exp_b_bfp_i (
        .clk_i      (clk_i),
        .rst_ni     (rst_ni),
        .pe_exp_b_i (pe_exp_b),
        .sel_b_i    (sel_b),
        .ctr_l_i    (ctr_l),
        .ctr_h_i    (ctr_h),
        .exp_b_dp8_o(exp_b_dp8)
    );

    pe_array_bfp pe_array_bfp_i (
        .clk_i        (clk_i),
        .rst_ni       (rst_ni),
        .a_dp8_i      (a_dp8),
        .b_dp8_i      (b_dp8),
        .is_signed_a_i(is_signed_a),
        .is_signed_b_i(is_signed_b),
        .exp_a_dp8_i  (exp_a_dp8),
        .exp_b_dp8_i  (exp_b_dp8),
        .sel_shift_i  (sel_shift),
        .en_level_i   (en_level),
        .l0_sum_o     (b_l0_sum),
        .l0_carry_o   (b_l0_carry),
        .l0_exp_o     (b_l0_exp),
        .l1_sum_o     (b_l1_sum),
        .l1_carry_o   (b_l1_carry),
        .l1_exp_o     (b_l1_exp),
        .l2_sum_o     (b_l2_sum),
        .l2_carry_o   (b_l2_carry),
        .l2_exp_o     (b_l2_exp),
        .l3_sum_o     (b_l3_sum),
        .l3_carry_o   (b_l3_carry),
        .l3_exp_o     (b_l3_exp)
    );

    acc_array_bfp acc_array_bfp_i (
        .clk_i       (clk_i),
        .rst_ni      (rst_ni),
        .l0_sum_i    (b_l0_sum),
        .l0_carry_i  (b_l0_carry),
        .l1_sum_i    (b_l1_sum),
        .l1_carry_i  (b_l1_carry),
        .l2_sum_i    (b_l2_sum),
        .l2_carry_i  (b_l2_carry),
        .l3_sum_i    (b_l3_sum),
        .l3_carry_i  (b_l3_carry),
        .l0_exp_i    (b_l0_exp),
        .l1_exp_i    (b_l1_exp),
        .l2_exp_i    (b_l2_exp),
        .l3_exp_i    (b_l3_exp),
        .acc_i       (acc_word),
        .acc_exp_i   (acc_exp_word),
        .sel_out_i   (sel_out),
        .sel_acc_i   (sel_acc),
        .prop_carry_i(prop_carry),
        .pe_out_o    (b_pe_out),
        .pe_exp_o    (b_pe_exp)
    );

    initial clk_i = 1'b0;
    always #(CLK_HALF) clk_i = ~clk_i;

    function automatic logic signed [15:0] rand_signed(input int width);
        logic [15:0] r;
        int pk;
        r = 16'($urandom);
        pk = $urandom % 5;
        case (width)
            4:       return (pk == 0) ? -16'sd8     : (pk == 1) ? 16'sd7     : 16'($signed(r[3:0]));
            8:       return (pk == 0) ? -16'sd128   : (pk == 1) ? 16'sd127   : 16'($signed(r[7:0]));
            default: return (pk == 0) ? -16'sd32768 : (pk == 1) ? 16'sd32767 : $signed(r);
        endcase
    endfunction

    function automatic logic signed [15:0] rand_signed_sym(input int width);
        int m;
        m = (1 << (width - 1)) - 1;
        return 16'($signed(($urandom % (2*m + 1)) - m));
    endfunction

    task automatic set_controls(input int mi);
        for (int p = 0; p < NUM_PAIR; p++) begin
            sel_a[p] = SEL_A[mi][p];
            sel_b[p] = SEL_B[mi][p];
            ctr_l[p] = CTR_L[mi][p];
            ctr_h[p] = CTR_H[mi][p];
        end
        for (int i = 0; i < NUM_DP8; i++) begin
            is_signed_a[i] = IS_SIGNED_A[mi][i];
            is_signed_b[i] = IS_SIGNED_B[mi][i];
        end
        sel_shift  = SEL_SHIFT[mi];
        en_level   = {TAP_LEVEL[mi] >= 3, TAP_LEVEL[mi] >= 2, TAP_LEVEL[mi] >= 1};
        sel_out    = 2'(TAP_LEVEL[mi]);
        prop_carry = (TAP_LEVEL[mi] >= 1);
    endtask

    function automatic longint read_result(input int lvl, input int node);
        int hlane, llane;
        if (lvl == 0) return longint'($signed(pe_out[node]));
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;    end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;             end
        endcase
        return longint'($signed({pe_out[hlane], pe_out[llane]}));
    endfunction

    function automatic int out_hlane(input int lvl, input int node);
        case (lvl)
            1:       return 2*node;
            2:       return (node==0)?2:6;
            default: return 6;
        endcase
    endfunction

    function automatic int out_llane(input int lvl, input int node);
        case (lvl)
            1:       return 2*node + 1;
            2:       return (node==0)?3:7;
            default: return 7;
        endcase
    endfunction

    function automatic longint read_result_bfp(input int lvl, input int node);
        if (lvl == 0) return longint'($signed(b_pe_out[node]));
        return longint'($signed({b_pe_out[out_hlane(lvl,node)], b_pe_out[out_llane(lvl,node)]}));
    endfunction

    function automatic logic [EXP_WIDTH-1:0] read_exp_bfp(input int lvl, input int node);
        if (lvl == 0) return b_pe_exp[node];
        return b_pe_exp[out_hlane(lvl,node)];
    endfunction

    function automatic longint resolve_tap_bfp(input int lvl, input int node);
        case (lvl)
            0:       return longint'($signed(b_l0_sum[node])) + longint'($signed(b_l0_carry[node]));
            1:       return longint'($signed(b_l1_sum[node])) + longint'($signed(b_l1_carry[node]));
            2:       return longint'($signed(b_l2_sum[node])) + longint'($signed(b_l2_carry[node]));
            default: return longint'($signed(b_l3_sum))       + longint'($signed(b_l3_carry));
        endcase
    endfunction

    task automatic set_acc_exp(input int lvl, input int node, input logic [EXP_WIDTH-1:0] e);
        if (lvl == 0) begin
            acc_exp_word[node] = e;
            return;
        end
        acc_exp_word[out_hlane(lvl,node)] = e;
        acc_exp_word[out_llane(lvl,node)] = e;
    endtask

    function automatic bit insub(input int d, input int lvl, input int node);
        int n;
        n = 2*(d/4) + (d%2);
        case (lvl)
            0:       return (n == node);
            1:       return (n/2 == node);
            2:       return (n/4 == node);
            default: return 1'b1;
        endcase
    endfunction

    function automatic logic [EXP_WIDTH-1:0] egold(input int lvl, input int node);
        logic [EXP_WIDTH-1:0] e;
        e = '0;
        for (int d = 0; d < NUM_DP8; d++)
            if (insub(d, lvl, node) && exp_dp8[d] > e) e = exp_dp8[d];
        return e;
    endfunction

    function automatic int ebias(input int base);
        int d;
        case ($urandom_range(0, 7))
            0:       d = 0;
            1:       d = 1;
            2:       d = 7;
            3:       d = 8;
            4:       d = 27;
            5:       d = 28;
            6:       d = 56;
            default: d = int'($urandom_range(0, 63));
        endcase
        if ($urandom_range(0, 1) == 1) d = -d;
        d = base + d;
        if (d < 0) d = 0;
        if (d > 63) d = 63;
        return d;
    endfunction

    task automatic set_exps(input int mi, input bit equal);
        int base;
        int ga [0:3];
        int gb [0:7];
        logic [5:0] ea [0:3];
        logic [5:0] eb [0:7];
        base = int'($urandom_range(0, 63));
        for (int g = 0; g < 4; g++) ga[g] = equal ? base : ebias(base);
        for (int g = 0; g < 8; g++) gb[g] = equal ? base : ebias(base);
        for (int blk = 0; blk < 4; blk++) ea[blk] = 6'(ga[EGRP_A[mi][blk]]);
        for (int h = 0; h < 8; h++)      eb[h]   = 6'(gb[EGRP_B[mi][h]]);
        for (int blk = 0; blk < NUM_BLK; blk++) begin
            pe_exp_a[blk*EXP_IN_WIDTH +: EXP_IN_WIDTH]           = ea[blk];
            pe_exp_b[blk*CHK_WIDTH+EXP_IN_WIDTH +: EXP_IN_WIDTH] = eb[2*blk];
            pe_exp_b[blk*CHK_WIDTH +: EXP_IN_WIDTH]              = eb[2*blk+1];
        end
        for (int p = 0; p < NUM_PAIR; p++) begin
            gold_exp_a[2*p]   = (CTR_H[mi][p] == 2'd1) ? '0 : ea[SEL_A[mi][p]];
            gold_exp_b[2*p]   = (CTR_H[mi][p] == 2'd1) ? '0 : eb[int'(SEL_B[mi][p])*2];
            gold_exp_a[2*p+1] = (CTR_L[mi][p] == 2'd1) ? '0 : ea[SEL_A[mi][p]];
            gold_exp_b[2*p+1] = (CTR_L[mi][p] == 2'd1) ? '0 : eb[int'(SEL_B[mi][p])*2+1];
        end
        for (int i = 0; i < NUM_DP8; i++)
            exp_dp8[i] = EXP_WIDTH'(gold_exp_a[i]) + EXP_WIDTH'(gold_exp_b[i]);
    endtask

    task automatic rand_matrices(input int mi);
        int M, K, N, PA, PB, cplx;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; PB = MM_DIMS[mi][4]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                A_re[m][k] = rand_signed(PA);
                A_im[m][k] = (cplx != 0) ? rand_signed(PA) : 16'sd0;
            end
        for (int k = 0; k < K; k++)
            for (int n = 0; n < N; n++) begin
                B_re[k][n] = rand_signed(PB);
                B_im[k][n] = (cplx != 0) ? rand_signed_sym(PB) : 16'sd0;
            end
    endtask

    task automatic golden(input int mi);
        int K, NOUT, m, n;
        longint re, im;
        K = MM_DIMS[mi][1]; NOUT = MM_DIMS[mi][6];
        for (int o = 0; o < NOUT; o++) begin
            m = MM_OUT[mi][o][0]; n = MM_OUT[mi][o][1];
            re = 0; im = 0;
            for (int k = 0; k < K; k++) begin
                re = re + longint'(A_re[m][k]) * longint'(B_re[k][n])
                        - longint'(A_im[m][k]) * longint'(B_im[k][n]);
                im = im + longint'(A_re[m][k]) * longint'(B_im[k][n])
                        + longint'(A_im[m][k]) * longint'(B_re[k][n]);
            end
            X_re[o] = re;
            X_im[o] = im;
        end
    endtask

    task automatic pack(input int mi);
        int M, K, N, PA, cplx, pos;
        pe_in_a = '0;
        pe_in_b = '0;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                pos = MM_RE_A[mi][m][k] & 255;
                if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][7:0];
                if (PA == 16) begin
                    pos = (MM_RE_A[mi][m][k] >> 8) & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][15:8];
                end
                if (cplx != 0) begin
                    pos = MM_IM_A[mi][m][k] & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][7:0];
                    if (PA == 16) begin
                        pos = (MM_IM_A[mi][m][k] >> 8) & 255;
                        if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][15:8];
                    end
                end
            end
        if (MODE_NUM[mi] == 12)
            pack_b_c16c16();
        else
            for (int k = 0; k < K; k++)
                for (int n = 0; n < N; n++)
                    for (int p = 0; p < 4; p++) begin
                        pos = (MM_RE_B[mi][k][n] >> (8*p)) & 255;
                        if (pos != 255) pe_in_b[pos*4 +: 4] = B_re[k][n][p*4 +: 4];
                        if (cplx != 0) begin
                            pos = (MM_IM_B[mi][k][n] >> (8*p)) & 255;
                            if (pos != 255) pe_in_b[pos*4 +: 4] = B_im[k][n][p*4 +: 4];
                        end
                    end
    endtask

    task automatic put_b16(input logic [15:0] v, input int blk_hi, input int blk_lo, input int lane);
        pe_in_b[(blk_hi*16 + 8 + lane)*4 +: 4] = v[15:12];
        pe_in_b[(blk_hi*16     + lane)*4 +: 4] = v[11:8];
        pe_in_b[(blk_lo*16 + 8 + lane)*4 +: 4] = v[7:4];
        pe_in_b[(blk_lo*16     + lane)*4 +: 4] = v[3:0];
    endtask

    task automatic pack_b_c16c16;
        for (int k = 0; k < 4; k++) begin
            put_b16( B_re[k][0], 0, 1, k);
            put_b16(-B_im[k][0], 0, 1, 4 + k);
            put_b16( B_im[k][0], 2, 3, k);
            put_b16( B_re[k][0], 2, 3, 4 + k);
        end
    endtask

    task automatic compare(input int mi);
        int NOUT, lvl, rn, in;
        longint r;
        NOUT = MM_DIMS[mi][6]; lvl = TAP_LEVEL[mi];
        for (int o = 0; o < NOUT; o++) begin
            rn = MM_OUT[mi][o][2];
            in = MM_OUT[mi][o][3];
            r = read_result(lvl, rn);
            if (r !== X_re[o]) begin
                err = err + 1;
                $display("mode %0d output %0d Re: golden=%0d dut=%0d", MODE_NUM[mi], o, X_re[o], r);
            end
            if (in >= 0) begin
                r = read_result(lvl, in);
                if (r !== X_im[o]) begin
                    err = err + 1;
                    $display("mode %0d output %0d Im: golden=%0d dut=%0d", MODE_NUM[mi], o, X_im[o], r);
                end
            end
        end
    endtask

    task automatic clear_acc;
        for (int j = 0; j < NUM_LANE; j++) acc_word[j] = '0;
    endtask

    task automatic set_acc(input int lvl, input int node, input longint val);
        int hlane, llane;
        if (lvl == 0) begin
            acc_word[node] = val[ACC_W-1:0];
            return;
        end
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;   end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;            end
        endcase
        acc_word[hlane] = val[2*ACC_W-1:ACC_W];
        acc_word[llane] = val[ACC_W-1:0];
    endtask

    longint acc_seed    [0:MAXO-1];
    longint acc_seed_im [0:MAXO-1];

    task automatic compare_bfp_equal(input int mi);
        int NOUT, lvl, rn, in;
        NOUT = MM_DIMS[mi][6]; lvl = TAP_LEVEL[mi];
        for (int j = 0; j < NUM_LANE; j++)
            if (b_pe_out[j] !== pe_out[j]) begin
                err = err + 1;
                $display("mode %0d equal-exp lane %0d: bfp %h base %h", MODE_NUM[mi], j, b_pe_out[j], pe_out[j]);
            end
        for (int o = 0; o < NOUT; o++) begin
            rn = MM_OUT[mi][o][2];
            in = MM_OUT[mi][o][3];
            if (read_exp_bfp(lvl, rn) !== egold(lvl, rn)) begin
                err = err + 1;
                $display("mode %0d out %0d Re exp: dut %0d gold %0d", MODE_NUM[mi], o, read_exp_bfp(lvl, rn), egold(lvl, rn));
            end
            if (in >= 0 && read_exp_bfp(lvl, in) !== egold(lvl, in)) begin
                err = err + 1;
                $display("mode %0d out %0d Im exp: dut %0d gold %0d", MODE_NUM[mi], o, read_exp_bfp(lvl, in), egold(lvl, in));
            end
        end
    endtask

    task automatic clear_acc_exp;
        for (int j = 0; j < NUM_LANE; j++) acc_exp_word[j] = '0;
    endtask

    function automatic longint seed_floor(input longint v, input int e);
        return v >>> ((e > 63) ? 63 : e);
    endfunction

    initial begin
        int err0, NOUT, lvl, rn, in;
        longint r, gexp;
        logic [EXP_WIDTH-1:0] etap;
        $display("\nStarting acc_array_bfp (full BFP chain vs baseline) verification (%0d modes x %0d random)...\n",
                 NUM_MODE, NUM_RAND);
`ifdef VCD
        $dumpfile("activity.vcd");
        $dumpvars(0, tb_acc_array_bfp.acc_array_bfp_i);
`endif

        rst_ni  = 1'b0;
        pe_in_a = '0;
        pe_in_b = '0;
        pe_exp_a = '0;
        pe_exp_b = '0;
        for (int p = 0; p < NUM_PAIR; p++) begin
            sel_a[p] = '0; sel_b[p] = '0; ctr_l[p] = '0; ctr_h[p] = '0;
        end
        for (int i = 0; i < NUM_DP8; i++) begin
            is_signed_a[i] = 1'b0; is_signed_b[i] = 1'b0;
            gold_exp_a[i] = '0; gold_exp_b[i] = '0; exp_dp8[i] = '0;
        end
        sel_shift = '0; en_level = '1; sel_out = '0; sel_acc = 1'b0; prop_carry = 1'b0;
        clear_acc();
        clear_acc_exp();
        err = 0; npass = 0;
        repeat (3) @(posedge clk_i);
        rst_ni = 1'b1;

        $display("Pass A - equal exponents (BFP == baseline, single-shot):");
        for (int mi = 0; mi < NUM_MODE; mi++) begin
            set_controls(mi);
            clear_acc();
            clear_acc_exp();
            sel_acc = 1'b0;
            err0 = err;
            for (int t = 0; t < NUM_RAND; t++) begin
                rand_matrices(mi);
                golden(mi);
                pack(mi);
                set_exps(mi, 1'b1);
                @(posedge clk_i);
                @(posedge clk_i);
                @(posedge clk_i);
                #(T_SETTLE);
                compare(mi);
                compare_bfp_equal(mi);
            end
            if (err == err0) begin
                npass = npass + 1;
                $display("  mode %0d: PASS", MODE_NUM[mi]);
            end else
                $display("  mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

        $display("\nPass A - equal exponents (accumulation: seed + %0d feedback iterations):", NUM_ACC);
        for (int mi = 0; mi < NUM_MODE; mi++) begin
            set_controls(mi);
            rand_matrices(mi);
            golden(mi);
            pack(mi);
            set_exps(mi, 1'b1);
            NOUT = MM_DIMS[mi][6];
            lvl  = TAP_LEVEL[mi];
            clear_acc();
            clear_acc_exp();
            for (int o = 0; o < NOUT; o++) begin
                acc_seed[o] = longint'(rand_signed(16));
                set_acc(lvl, MM_OUT[mi][o][2], acc_seed[o]);
                set_acc_exp(lvl, MM_OUT[mi][o][2], egold(lvl, MM_OUT[mi][o][2]));
                if (MM_OUT[mi][o][3] >= 0) begin
                    acc_seed_im[o] = longint'(rand_signed(16));
                    set_acc(lvl, MM_OUT[mi][o][3], acc_seed_im[o]);
                    set_acc_exp(lvl, MM_OUT[mi][o][3], egold(lvl, MM_OUT[mi][o][3]));
                end
            end
            sel_acc = 1'b0;
            repeat (3) @(posedge clk_i);
            #(T_SETTLE);
            for (int it = 1; it < NUM_ACC; it++) begin
                sel_acc = 1'b1;
                @(posedge clk_i);
            end
            #(T_SETTLE);
            err0 = err;
            for (int o = 0; o < NOUT; o++) begin
                rn = MM_OUT[mi][o][2];
                in = MM_OUT[mi][o][3];
                r    = read_result(lvl, rn);
                gexp = acc_seed[o] + NUM_ACC * X_re[o];
                if (r !== gexp) begin
                    err = err + 1;
                    $display("  acc mode %0d out %0d Re: golden=%0d dut=%0d", MODE_NUM[mi], o, gexp, r);
                end
                if (read_result_bfp(lvl, rn) !== r) begin
                    err = err + 1;
                    $display("  acc mode %0d out %0d Re: bfp=%0d base=%0d", MODE_NUM[mi], o, read_result_bfp(lvl, rn), r);
                end
                if (read_exp_bfp(lvl, rn) !== egold(lvl, rn)) begin
                    err = err + 1;
                    $display("  acc mode %0d out %0d Re exp: dut %0d gold %0d", MODE_NUM[mi], o, read_exp_bfp(lvl, rn), egold(lvl, rn));
                end
                if (in >= 0) begin
                    r    = read_result(lvl, in);
                    gexp = acc_seed_im[o] + NUM_ACC * X_im[o];
                    if (r !== gexp) begin
                        err = err + 1;
                        $display("  acc mode %0d out %0d Im: golden=%0d dut=%0d", MODE_NUM[mi], o, gexp, r);
                    end
                    if (read_result_bfp(lvl, in) !== r) begin
                        err = err + 1;
                        $display("  acc mode %0d out %0d Im: bfp=%0d base=%0d", MODE_NUM[mi], o, read_result_bfp(lvl, in), r);
                    end
                    if (read_exp_bfp(lvl, in) !== egold(lvl, in)) begin
                        err = err + 1;
                        $display("  acc mode %0d out %0d Im exp: dut %0d gold %0d", MODE_NUM[mi], o, read_exp_bfp(lvl, in), egold(lvl, in));
                    end
                end
            end
            if (err == err0)
                $display("  acc mode %0d: PASS", MODE_NUM[mi]);
            else
                $display("  acc mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

        $display("\nPass B - BFP exponents, min-scale seed (accumulation, exact vs BFP tap):");
        for (int mi = 0; mi < NUM_MODE; mi++) begin
            set_controls(mi);
            rand_matrices(mi);
            golden(mi);
            pack(mi);
            NOUT = MM_DIMS[mi][6];
            lvl  = TAP_LEVEL[mi];
            err0 = err;
            for (int t = 0; t < NUM_RAND; t++) begin
                rand_matrices(mi);
                pack(mi);
                set_exps(mi, 1'b0);
                clear_acc();
                clear_acc_exp();
                for (int o = 0; o < NOUT; o++) begin
                    acc_seed[o] = longint'(rand_signed(16));
                    set_acc(lvl, MM_OUT[mi][o][2], acc_seed[o]);
                    if (MM_OUT[mi][o][3] >= 0) begin
                        acc_seed_im[o] = longint'(rand_signed(16));
                        set_acc(lvl, MM_OUT[mi][o][3], acc_seed_im[o]);
                    end
                end
                sel_acc = 1'b0;
                repeat (3) @(posedge clk_i);
                #(T_SETTLE);
                for (int it = 1; it < NUM_ACC; it++) begin
                    sel_acc = 1'b1;
                    @(posedge clk_i);
                end
                #(T_SETTLE);
                for (int o = 0; o < NOUT; o++) begin
                    rn = MM_OUT[mi][o][2];
                    in = MM_OUT[mi][o][3];
                    etap = egold(lvl, rn);
                    gexp = seed_floor(acc_seed[o], int'(etap)) + NUM_ACC * resolve_tap_bfp(lvl, rn);
                    if (read_result_bfp(lvl, rn) !== gexp) begin
                        err = err + 1;
                        $display("  B mode %0d out %0d Re: bfp=%0d model=%0d (etap %0d)",
                                 MODE_NUM[mi], o, read_result_bfp(lvl, rn), gexp, etap);
                    end
                    if (read_exp_bfp(lvl, rn) !== etap) begin
                        err = err + 1;
                        $display("  B mode %0d out %0d Re exp: dut %0d gold %0d", MODE_NUM[mi], o, read_exp_bfp(lvl, rn), etap);
                    end
                    if (in >= 0) begin
                        etap = egold(lvl, in);
                        gexp = seed_floor(acc_seed_im[o], int'(etap)) + NUM_ACC * resolve_tap_bfp(lvl, in);
                        if (read_result_bfp(lvl, in) !== gexp) begin
                            err = err + 1;
                            $display("  B mode %0d out %0d Im: bfp=%0d model=%0d (etap %0d)",
                                     MODE_NUM[mi], o, read_result_bfp(lvl, in), gexp, etap);
                        end
                        if (read_exp_bfp(lvl, in) !== etap) begin
                            err = err + 1;
                            $display("  B mode %0d out %0d Im exp: dut %0d gold %0d", MODE_NUM[mi], o, read_exp_bfp(lvl, in), etap);
                        end
                    end
                end
            end
            if (err == err0)
                $display("  B mode %0d: PASS", MODE_NUM[mi]);
            else
                $display("  B mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

`ifdef VCD
        $dumpoff;
`endif
        $display("\nacc_array_bfp verification: %0d/%0d Pass-A single-shot modes passed (%0d total mismatches)\n",
                 npass, NUM_MODE, err);
        $finish;
    end

endmodule
